#!/usr/bin/env bash
set -euo pipefail

REPO="$PWD"
TAG="v1.0.24.23"
EXPECTED_SHA="2a0932d0be6bae78bda87c2d2df673ff39c0b78fb44ffc662bfb437d14e6a4ed"

fail() { echo "ERROR: $*" >&2; exit 1; }

command -v git >/dev/null || fail "git is not installed"
command -v python3 >/dev/null || fail "python3 is not installed"
command -v unzip >/dev/null || fail "unzip is not installed"
command -v rsync >/dev/null || fail "rsync is not installed"
command -v sha256sum >/dev/null || fail "sha256sum is not installed"

[[ -d "$REPO/.git" ]] || fail "Repository not found: $REPO"
git -C "$REPO" remote get-url origin >/dev/null 2>&1 || fail "No origin remote configured"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
PAYLOAD="$TMP/atlas-public-source.zip"

echo "[1/6] Restoring verified Atlas v1.0.24.23 public source..."
base64 -d > "$PAYLOAD" <<'__ATLAS_PAYLOAD__'

__ATLAS_PAYLOAD__

[[ "$(sha256sum "$PAYLOAD" | awk '{print $1}')" == "$EXPECTED_SHA" ]] || fail "Source SHA mismatch"

mkdir -p "$TMP/src"
unzip -q "$PAYLOAD" -d "$TMP/src"
SRC="$(find "$TMP/src" -mindepth 1 -maxdepth 1 -type d | head -1)"
[[ -d "$SRC" ]] || fail "Could not locate source root"

echo "[2/6] Backing up current repository working tree..."
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$HOME/CodeCafe_Atlas_GitHub_before_${TAG}_${STAMP}.tar.gz"
tar -C "$REPO" --exclude='.git' -czf "$BACKUP" .

echo "[3/6] Replacing working tree, preserving .git..."
rsync -a --delete \
  --exclude='.git/' \
  --exclude='.venv/' --exclude='venv/' \
  --exclude='build/' --exclude='dist/' --exclude='__pycache__/' \
  "$SRC/" "$REPO/"

cd "$REPO"

echo "[4/6] Validating exact tree to publish..."
python3 validate_public_identity.py
python3 validate_full_functionality.py
python3 validate_before_build.py

# Explicitly reject the private documentation package if somehow present.
[[ ! -d docs ]] || fail "Private docs/ directory is present; refusing to publish."
[[ ! -f TECHNICAL_DOCUMENTATION.md ]] || fail "Private technical documentation is present; refusing to publish."

if find . -path './.git' -prune -o -type f \( \
  -iname '*.db' -o -iname '*.sqlite' -o -iname '*.sqlite3' \
  -o -iname '*.pem' -o -iname '*.key' -o -iname '.env' \
\) -print | grep -q .; then
  fail "Runtime database/secret file found; refusing to publish."
fi

git add -A

echo "[5/6] Committing and tagging v1.0.24.23..."
if ! git diff --cached --quiet; then
  git commit -m "CodeCafe Atlas v1.0.24.23"
fi

if git rev-parse "$TAG" >/dev/null 2>&1; then
  git tag -d "$TAG" >/dev/null
fi
git tag -a "$TAG" -m "CodeCafe Atlas v1.0.24.23"

echo "[6/6] Pushing to GitHub..."
BRANCH="$(git branch --show-current)"
[[ -n "$BRANCH" ]] || fail "Could not determine current branch"
git push origin "$BRANCH"
git push --force origin "$TAG"

echo
echo "SUCCESS: CodeCafe Atlas v1.0.24.23 uploaded."
echo "Private technical documentation was NOT included."
echo "Repository backup: $BACKUP"
echo "Published source SHA-256: $EXPECTED_SHA"
